const r = await tools.exec_command({cmd:"python3 - <<'PY'
import h5py, numpy as np
for p in ['/app/data/sub-m12/sub-m12_ses-01_behavior+ophys.nwb','/app/data/sub-m12/sub-m12_ses-03_behavior+ophys.nwb']:
 print('\nFILE',p)
 with h5py.File(p,'r') as f:
  print('identifier',f['identifier'][()].decode())
  for key in ['processing/behavior/BehavioralTimeSeries/Reward','processing/ophys/Deconvolved/plane0','processing/ophys/Fluorescence/plane0']:
   g=f[key]
   print(key, 'group attrs',dict(g.attrs))
   for child in g:
    obj=g[child]
    if isinstance(obj,h5py.Dataset):
     vals=obj[:]
     print(' ',child,vals.shape,vals.dtype,'attrs',dict(obj.attrs),'first',vals.reshape(-1)[:10])
  ic=f['processing/ophys/ImageSegmentation/PlaneSegmentation/iscell'][:]
  print('iscell',ic.shape,'counts',np.unique(ic[:,0],return_counts=True),'prob range',ic[:,1].min(),ic[:,1].max())
  root='processing/behavior/BehavioralTimeSeries/'
  a={k:f[root+k+'/data'][:] for k in ['trial_start','teleport','trial number','position','environment','reward_zone']}
  si=np.flatnonzero(a['trial_start']>0); ei=np.flatnonzero(a['teleport']>0)
  print('starts',len(si),si[:5],si[-3:],'ends',len(ei),ei[:5],ei[-3:])
  for j in range(min(3,len(si))):
   lo=si[j]; hi=ei[j]
   print(' trial',j,'slice',lo,hi,'trialnum unique',np.unique(a['trial number'][lo:hi]),'pos endpoints',a['position'][lo:lo+3],a['position'][hi-3:hi], 'env',np.unique(a['environment'][lo:hi]),'rzsum',a['reward_zone'][lo:hi].sum())
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":20000});
