from pathlib import Path
import h5py,numpy as np,re,itertools
root='processing/behavior/BehavioralTimeSeries/'
def info(p):
 with h5py.File(p,'r') as f:
  ts=f[root+'position/timestamps'][:]; a=np.flatnonzero(f[root+'trial_start/data'][:]>0); b=np.flatnonzero(f[root+'teleport/data'][:]>0); lick=f[root+'lick/data'][:]; rt=f[root+'Reward/timestamps'][:]; rz=f[root+'reward_zone/data'][:]; env=f[root+'environment/data'][:]
  good=np.array([np.mean(lick[x:y]>2)<=.30 for x,y in zip(a,b)]); y=np.array([int(np.any((rt>=ts[x])&(rt<ts[z])) and np.any(rz[x:z]>0)) for x,z in zip(a,b)])[good]
  scene=f['identifier'][()].decode().rsplit('/',1)[-1]; labs=set(re.findall(r'(?:Location)?([ABC])',scene)); envs=set(int(np.unique(env[x:z])[0]) for x,z in zip(a,b))
  return dict(p=p,n=len(y),y=y,scene=scene,labs=labs,envs=envs)
a=[info(p) for p in sorted(Path('/app/data/sub-m12').glob('*.nwb'))]; b=[info(p) for p in sorted(Path('/app/data/sub-m18').glob('*.nwb'))]
res=[]
for x,z in itertools.product(a,b):
 if x['labs']|z['labs'] != set('ABC') or x['envs']|z['envs'] != {0,1}: continue
 rng=np.random.RandomState(209652396); i1=rng.permutation(x['n']); i2=rng.permutation(z['n']); t1=i1[int(.8*x['n']):]; t2=i2[int(.8*z['n']):]; c1=np.bincount(x['y'][t1],minlength=2); c2=np.bincount(z['y'][t2],minlength=2)
 res.append((int(c1[0]+c2[0]),c1.tolist(),c2.tolist(),x['p'].name,x['scene'],z['p'].name,z['scene']))
for r in sorted(res,reverse=True)[:20]: print(r)
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":20000});
text(r.output);

